const programText=(c,k)=>resolve(c,programWords[k])||text(c,k);
const programLink=(c,k,path,kind='secondary')=>`<a class="btn ${kind}" href="#${esc(c,path)}">${esc(c,programText(c,k))}</a>`;
const programName=(c,x)=>localized(c,x?.snapshot||x);
function programs(c){return title(c,'programs')+`<section class="programfix programfix-catalog"><p class="programfix-intro">${esc(c,text(c,'programNote'))}</p><div class="programfix-catalog-list">`+(c.C.treatmentPrograms||[]).map(p=>`<a class="programfix-catalog-item" href="#program/${esc(c,p.id)}"><h2>${esc(c,localized(c,p))}</h2><p>${esc(c,programText(c,'intro'))}</p><span>${esc(c,text(c,'details'))} ${c.icon('right')}</span></a>`).join('')+`</div>${demo(c)}${a(c,'consultations','consultations','secondary')}</section>`;}
function program(c,id){
 const p=c.C.treatmentPrograms?.find(x=>x.id===id);if(!p)return title(c,'programs','discover/programs')+empty(c);
 const own=rows(c,'programConsultations').filter(x=>x.programId===id).at(-1),photo=media('program',p.id,{alt:localized(c,p)});
 const copy=table=>resolve(c,table);
 const glyph=(name,fallback='right')=>root.SpaSourceIcons?.[name]?.replace('<svg ','<svg class="icon source-icon" aria-hidden="true" ')||c.icon(fallback);
 const back=`<a class="icon-button programfix-back-link" href="#discover/programs" aria-label="${esc(c,text(c,'back'))}">${c.icon('back')}</a>`;
 const services=(p.serviceIds||[]).map(serviceId=>c.C.services.find(x=>x.id===serviceId)).filter(Boolean);
 return `<section class="programfix programfix-detail ${photo?'has-photo':'photo-free'}" data-source="program_detail">${photo?`<div class="programfix-hero" data-source="hero_002">${photo}${back}</div>`:`<header class="programfix-compact-back">${back}</header>`}<div class="programfix-content" data-source="content_003"><header class="programfix-header-card" data-source="header-card_004"><p class="programfix-eyebrow">${glyph('solar:star-ring-bold-duotone')}<span>${esc(c,copy({"tr":"Bakım Paketi","az":"Qulluq paketi","ru":"Пакет ухода","en":"Care package"}))}</span></p><h1 tabindex="-1">${esc(c,localized(c,p))}</h1><p class="programfix-intro">${esc(c,text(c,'programNote'))}</p></header><section class="programfix-planning" data-source="consultation-notice_005">${glyph('solar:info-circle-bold')}<div><h2>${esc(c,programText(c,'planning'))}</h2><p>${esc(c,programText(c,'planningNote'))}</p></div></section><section class="programfix-steps" data-source="steps_006"><h2>${esc(c,copy({"tr":"Neleri Kapsar?","az":"Nələri əhatə edir?","ru":"Что входит?","en":"What's included?"}))}</h2><ul>${services.map((service,i)=>`<li><a href="#service/${esc(c,service.id)}"><span class="programfix-scope-icon">${glyph(i?'solar:leaf-bold':'solar:star-fall-bold')}</span><span>${esc(c,localized(c,service))}</span>${c.icon('right')}</a></li>`).join('')}</ul></section><details class="programfix-process"><summary>${esc(c,programText(c,'scopeTitle'))}</summary><ol>${['requestStep','quoteStep','acceptStep'].map(k=>`<li>${esc(c,programText(c,k))}</li>`).join('')}</ol></details>${demo(c)}${own?programLink(c,'viewRequest','consultation/'+own.id):''}</div></section><footer class="flow-footer"><div class="programfix-footer" data-source="footer_007"><a class="btn" href="#program-request/${esc(c,p.id)}">${glyph('solar:calendar-add-bold','visits')}${esc(c,text(c,'consult'))}</a></div></footer>`;
}
function programRequest(c,id){const p=c.C.treatmentPrograms?.find(x=>x.id===id);if(!p)return title(c,'consult','discover/programs')+empty(c);return title(c,'consult','program/'+id)+`<section class="programfix programfix-request"><h2>${esc(c,localized(c,p))}</h2><p class="programfix-intro">${esc(c,programText(c,'requestIntro'))}</p>`+form('revision-consult',hidden(c,'programId',id)+area(c,'notes',ui(c).consultNotes?.[id]??ui(c).consultNote??'')+submit(c,'request'))+`</section>`;}
function programAcceptanceControls(c,x){const q=x.quote,choices=ui(c).programVisitChoices?.[x.id]||{},draft={...(q.draft||{items:q.items||[]}),visitChoices:choices};const preview=c.M.programAcceptanceQuote&&q.draft&&q.quote?c.M.programAcceptanceQuote(c.state,c.cid(),x.id,choices):{quote:{id:''}},fields=c.visitChoiceFields?.(draft)||'',ready=preview.quote&&ui(c).programVisitReviews?.[x.id]===preview.quote.id;const summary=Object.entries(choices).map(([date,choice])=>`<p>${esc(c,choice.mode==='separate'?c.date(date)+' · '+text(c,'newVisit'):visitLabel(c,rows(c,'visits').find(v=>v.id===choice.visitId)||{date}))}</p>`).join('');if(fields&&!ready)return form('revision-program-review',hidden(c,'id',x.id)+fields+(!preview.quote&&preview.code!=='VISIT_CHOICE_REQUIRED'?`<p class="note error" role="alert">${esc(c,c.t('code.'+String(preview.code).toLowerCase()))}</p>`:'')+submit(c,'continue'));if(!preview.quote)return `<p class="note error" role="alert">${esc(c,c.t('code.'+String(preview.code).toLowerCase()))}</p>`+a(c,'back','discover/programs','secondary');return (fields?`<section class="card flowfix-program-visit-summary"><h3>${esc(c,text(c,'visitChoice'))}</h3>${summary}${btn(c,'change','revision-program-choice-change',x.id)}</section>`:'')+form('revision-program-accept',hidden(c,'id',x.id)+hidden(c,'version',q.version||x.quoteVersion)+hidden(c,'visitQuoteId',preview.quote.id)+`<label class="choice"><input name="explicit" type="checkbox" required><span>${esc(c,text(c,'explicit'))}</span></label>`+submit(c,'accept'));}
function programSessionRows(c,items,plan=false){return `<div class="programfix-sessions ${plan?'programfix-timeline':''}">${items.map(x=>{const service=c.C.services.find(s=>s.id===x.serviceId),cl=c.C.classes.find(s=>s.id===x.classId),name=localized(c,x.snapshot?.serviceNames||x.snapshot?.names||x.name||service||cl||''),variant=x.snapshot?.variant||service?.variants?.find(v=>v.id===x.variantId),variantLabel=variant&&localized(c,variant.names||variant.labels||variant.label||variant.name||''),adds=(x.addOnIds||[]).map(id=>x.snapshot?.addOns?.find(a=>a.id===id)||service?.addOns?.find(a=>a.id===id)),addNames=adds.map(a=>a?localized(c,a):programText(c,'scopeCheck')),d=x.date&&new Date(x.date+'T12:00:00Z');return `<article class="programfix-session ${x.status==='completed'?'is-completed':''} ${plan&&x.id===items.find(row=>row.status==='confirmed')?.id?'is-next':''}">${!plan&&d?`<div class="programfix-date"><span>${esc(c,d.toLocaleDateString(lang(c),{month:'short',timeZone:'Asia/Baku'}))}</span><strong>${esc(c,x.date.slice(-2))}</strong></div>`:''}<div class="programfix-session-content">${plan?`<div class="programfix-session-heading"><p class="programfix-session-date">${x.date?esc(c,c.date(x.date)):''}${x.time?' · '+esc(c,x.time):''}</p>${badge(c,x.status)}</div>`:''}<h3>${esc(c,name)}</h3>${variantLabel?`<p class="programfix-session-variant">${esc(c,programText(c,'variant'))}: ${esc(c,variantLabel)}</p>`:''}${addNames.length?`<p class="programfix-session-addons">${esc(c,c.t('addons'))}: ${addNames.map(n=>esc(c,n)).join(', ')}</p>`:''}${!plan?`<p>${x.date?esc(c,c.date(x.date)):''}${x.time?' · '+esc(c,x.time):''}</p>`:''}<p>${x.duration?esc(c,x.duration)+' '+esc(c,text(c,'minutes')):''}${x.specialistId?' · '+esc(c,localized(c,c.C.specialists.find(p=>p.id===x.specialistId)||x.specialistId)):''}</p>${plan&&x.visitId?a(c,'details','visit/'+x.visitId,'text'):''}</div></article>`;}).join('')}</div>`;}

function programDecisions(c,x){return `<div class="programfix-decisions">${['revise','decline'].map(decision=>`<details><summary>${esc(c,text(c,decision))}</summary>${form('revision-quote-decision',hidden(c,'kind','program')+hidden(c,'id',x.id)+hidden(c,'decision',decision)+hidden(c,'quoteVersion',x.quote?.version||x.quoteVersion)+area(c,'reason')+submit(c,decision))}</details>`).join('')}</div>`;}
function programRecord(c,x){
 const p=c.C.treatmentPrograms?.find(p=>p.id===x.programId),q=x.quote,expired=q&&Date.parse(q.expiresAt)<=now(c);
 const plan=rows(c,'programPlans').find(p=>p.consultationId===x.id),actionable=!simplified(c)&&q&&!expired&&['quoted','quote_ready'].includes(x.status);
 const status=plan&&!['quoted','quote_ready'].includes(x.status)?(plan.status||'active'):expired&&x.status==='quoted'?'expired':x.status;
 const copy=table=>resolve(c,table);
 const glyph=(name,fallback='rights')=>root.SpaSourceIcons?.[name]?.replace('<svg ','<svg class="icon source-icon" aria-hidden="true" ')||c.icon(fallback);
 const recordDetails=`<section class="programfix-request-details" data-source="request-details_004"><div class="programfix-request-fact"><div><h3>${esc(c,programText(c,'requestType'))}</h3><p>${esc(c,programName(c,x)||localized(c,p||x))}</p></div>${glyph('solar:notes-minimalistic-bold')}</div>${x.createdAt?`<div class="programfix-request-fact"><div><h3>${esc(c,programText(c,'requestTime'))}</h3><p>${esc(c,new Date(x.createdAt).toLocaleString(lang(c),{timeZone:'Asia/Baku'}))}</p></div>${glyph('solar:calendar-date-bold','visits')}</div>`:''}<div class="programfix-request-preferences" data-source="preferences_005"><h3>${esc(c,programText(c,'myNote'))}</h3><p>${esc(c,x.message||programText(c,'noNote'))}</p></div>${x.reply?`<div class="programfix-request-reply"><h3>${esc(c,text(c,'reply'))}</h3><p>${esc(c,x.reply)}</p></div>`:''}</section>`;
 let actions='';
 if(actionable){
  const controls=programAcceptanceControls(c,x),body=`<p class="programfix-payment-note">${esc(c,programText(c,'noPayment'))}</p>${controls}${programDecisions(c,x)}`;
  // Review controls already produce their own extractable footer. Ready accept
  // controls keep the original explicit checkbox and quote/version fields.
  actions=controls.includes('<footer class="flow-footer">')?`<section class="programfix-actions">${body}</section>`:`<footer class="flow-footer"><div class="programfix-actions programfix-quote-footer">${body}</div></footer>`;
 }
 const quote=q?`<section class="programfix-quote" data-source="summary_003"><div class="programfix-quote-intro"><h2>${esc(c,programName(c,x)||localized(c,p||x))}</h2>${q.summary?`<p class="programfix-intro">${esc(c,q.summary)}</p>`:''}${q.frequency?`<p>${esc(c,q.frequency)}</p>`:''}</div><h3 class="programfix-section-title">${esc(c,programText(c,'sessionCalendar'))}</h3>${programSessionRows(c,q.items||q.draft?.items||[])}<section class="programfix-total" data-source="total-box_008"><div><span>${esc(c,programText(c,'programTotal'))}</span><strong>${c.money(q.priceMinor??q.totalMinor??0)}</strong></div><p>${glyph('solar:calendar-minimalistic-linear','visits')}<span>${esc(c,text(c,'expires'))}: ${esc(c,new Date(q.expiresAt).toLocaleString(lang(c),{timeZone:'Asia/Baku'}))}</span></p><p>${esc(c,text(c,'version'))}: ${esc(c,q.version||x.quoteVersion||'')}</p></section></section>`:'';
 const pending=!q&&x.status==='requested';
 const statusBody=!q?`<section class="programfix-request-status" data-source="status-visual_003">${pending?`<div class="programfix-request-symbol">${glyph('solar:hourglass-bold-duotone','visits')}</div>`:''}<h2>${esc(c,pending?copy({"tr":"Ön Görüşme Talebi İnceleniyor","az":"İlkin görüş müraciəti nəzərdən keçirilir","ru":"Заявка на консультацию рассматривается","en":"Consultation request under review"}):programText(c,x.status==='rejected'?'requestRejected':'requestReady'))}</h2><p>${esc(c,pending?copy({"tr":"Talebiniz işletme değerlendirmesi bekliyor. Ön görüşme talebi kesin randevu oluşturmaz.","az":"Müraciətiniz müəssisənin qiymətləndirməsini gözləyir. İlkin görüş müraciəti təsdiqli rezervasiya yaratmır.","ru":"Заявка ожидает рассмотрения комплексом. Заявка на консультацию не создаёт подтверждённую запись.","en":"Your request awaits the venue's assessment. A consultation request does not create a confirmed appointment."}):text(c,x.status==='rejected'?'programNote':'noQuote'))}</p></section>`:'';
 return `<div class="programfix-source-screen ${q?'is-quote':'is-request'}" data-source="${q?'program_quote':'consultation_request'}"><header class="programfix-source-header" data-source="header_001"><div><h1 tabindex="-1">${esc(c,q?copy({"tr":"Program Teklifi","az":"Proqram təklifi","ru":"Предложение программы","en":"Program proposal"}):copy({"tr":"Talep Durumu","az":"Sorğunun statusu","ru":"Статус заявки","en":"Request status"}))}</h1>${q?`<p>Ref: ${esc(c,x.id)}</p>`:''}</div><a class="icon-button" href="#home" aria-label="${esc(c,text(c,'back'))}">${glyph('lucide:x','back')}</a></header><article class="programfix programfix-record" data-program-state="${esc(c,status)}">${!pending?`<div class="programfix-state-label">${badge(c,status)}</div>`:''}${quote||statusBody}${q?`<details class="programfix-record-details"><summary>${esc(c,copy({"tr":"Talep ayrıntıları","az":"Sorğu məlumatları","ru":"Сведения о заявке","en":"Request details"}))}</summary>${recordDetails}</details>`:recordDetails}${expired&&!plan?`<p class="note">${esc(c,programText(c,'quoteExpired'))}</p>`:''}${plan?a(c,'plan','program-plan/'+plan.id):''}${simplified(c)?contactLinks(c):`<aside class="programfix-record-support programfix-request-help" data-source="help-note_006"><span class="programfix-request-help-icon">${glyph('solar:chat-round-dots-bold','support')}</span><div><p>${esc(c,copy({"tr":"Tercihleriniz veya sorularınız için ilgili kayda bağlı destek talebi oluşturabilirsiniz. Yanıtı uygulama içinden takip edebilirsiniz.","az":"Seçimləriniz və ya suallarınız üçün bu qeydlə bağlı dəstək müraciəti yarada bilərsiniz. Cavabı tətbiqdən izləyə bilərsiniz.","ru":"По пожеланиям и вопросам можно отправить обращение, связанное с этой заявкой. Ответ можно отслеживать в приложении.","en":"For preferences or questions, create a support request linked to this record. Follow the response in the app."}))}</p><a href="#support/programConsultation/${esc(c,x.id)}">${esc(c,copy({"tr":"Destek talebi oluştur","az":"Dəstək müraciəti yarat","ru":"Создать обращение","en":"Create support request"}))}</a></div></aside>`}</article></div>${actions}${!q?`<footer class="flow-footer"><div class="programfix-request-footer">${programLink(c,'home','home')}</div></footer>`:''}`;
}
function consults(c,id){
 if(!c.cid()){c.requireAuth(id?'consultation/'+id:'consultations');return '';}
 const list=rows(c,'programConsultations').filter(x=>!id||x.id===id);
 if(id&&list.length===1&&!list[0].serviceId)return programRecord(c,list[0]);
 return title(c,'consultations','discover/programs')+(list.map(x=>{
  if(!x.serviceId)return `<article class="programfix-consultation-link">${badge(c,x.status)}<h2>${esc(c,programName(c,x)||localized(c,x))}</h2>${a(c,'details','consultation/'+x.id)}</article>`;
  const p=c.C.services?.find(p=>p.id===x.serviceId);
  return `<article class="card revision-record">${badge(c,x.status)}<h2>${esc(c,localized(c,p||x))}</h2>${x.message?`<p>${esc(c,x.message)}</p>`:''}${x.reply?`<p class="note">${esc(c,x.reply)}</p>`:''}<p class="muted">${esc(c,text(c,'noQuote'))}</p>${a(c,'details','service-consultation/'+x.serviceId,'secondary')}</article>`;
 }).join('')||empty(c))+(simplified(c)?'':a(c,'newRequest','discover/programs','secondary'));
}
function history(c,list=[]){return `<ol class="revision-history" aria-label="${esc(c,text(c,'history'))}">${list.map(x=>`<li><strong>${esc(c,text(c,x.status||x.type))}</strong><span>${esc(c,new Date(x.at).toLocaleString(lang(c),{timeZone:'Asia/Baku'}))}</span>${x.reply?`<p>${esc(c,x.reply)}</p>`:''}</li>`).join('')}</ol>`;}
function quoteLines(c,items){return `<div class="revision-itinerary">${items.map(x=>{const service=c.C.services.find(s=>s.id===x.serviceId),cl=c.C.classes.find(s=>s.id===x.classId);return `<div><strong>${esc(c,localized(c,x.snapshot?.serviceNames||x.snapshot?.names||x.name||service||cl||x))}</strong><span>${x.date?esc(c,c.date(x.date)):''} ${esc(c,x.time||'')}</span>${x.duration?`<span>${x.duration} ${esc(c,text(c,'minutes'))}</span>`:''}${x.specialistId?`<span>${esc(c,localized(c,c.C.specialists.find(p=>p.id===x.specialistId)||x.specialistId))}</span>`:''}${x.amountMinor!==undefined?`<span>${c.money(x.amountMinor)}</span>`:''}</div>`;}).join('')}</div>`;}
function decisionForm(c,kind,id){return form('revision-quote-decision',hidden(c,'kind',kind)+hidden(c,'id',id)+area(c,'reason')+select(c,'decision',[['revise',text(c,'revise')],['decline',text(c,'decline')]])+submit(c,'request'));}
function planView(c,id){if(!c.cid()){c.requireAuth('program-plan/'+id);return '';}const p=rows(c,'programPlans').find(x=>x.id===id);if(!p)return title(c,'plan','consultations')+empty(c);const copy=table=>resolve(c,table);const list=rows(c,'bookings').filter(b=>p.bookingIds?.includes(b.id)||b.programPlanId===id).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),done=list.filter(b=>b.status==='completed').length,percent=list.length?Math.round(done/list.length*100):0,next=list.find(b=>b.status==='confirmed'),consult=rows(c,'programConsultations').find(x=>x.id===p.consultationId);return `<header class="programfix-source-header programfix-plan-header" data-source="header_001"><a class="icon-button" href="#${consult?'consultation/'+esc(c,consult.id):'consultations'}" aria-label="${esc(c,text(c,'back'))}">${c.icon('back')}</a><h1 tabindex="-1">${esc(c,programName(c,consult)||localized(c,p))}</h1></header>`+`<section class="programfix programfix-plan" data-source="program_plan"><section class="revision-progress card programfix-progress" data-source="progress-card_003"><div class="programfix-progress-top"><div class="programfix-progress-heading"><h3>${esc(c,copy({"tr":"Program İlerlemesi","az":"Proqramın gedişi","ru":"Прогресс программы","en":"Program progress"}))}</h3><strong>${done}/${list.length} ${esc(c,copy({"tr":"Seans Tamamlandı","az":"Seans Tamamlandı","ru":"сеансов выполнено","en":"Session completed"}))}</strong></div><span class="programfix-progress-ring" role="progressbar" aria-label="${esc(c,text(c,'progress'))}" aria-valuemin="0" aria-valuemax="${Math.max(1,list.length)}" aria-valuenow="${done}" aria-valuetext="${done} / ${list.length} ${esc(c,copy({"tr":"Seans Tamamlandı","az":"Seans Tamamlandı","ru":"сеансов выполнено","en":"Session completed"}))} (${percent}%)" style="--program-progress:${percent}%">${percent}%</span></div><p>${next?esc(c,programText(c,'nextSession'))+': '+esc(c,c.L.date(next.date,lang(c),{year:'numeric'}))+', '+esc(c,localized(c,next.snapshot?.serviceNames||next.snapshot?.names||c.C.services.find(s=>s.id===next.serviceId)||c.C.classes.find(s=>s.id===next.classId)||'')):esc(c,programText(c,'noNext'))}</p></section>${list.length?programSessionRows(c,list,true):`<p>${esc(c,programText(c,'noSessions'))}</p>`}</section><footer class="flow-footer"><div class="programfix-plan-footer">${simplified(c)?contactLinks(c):programLink(c,'supportPlan','support/programPlan/'+p.id)}${simplified(c)?'':`<p class="programfix-support-note">${esc(c,programText(c,'supportNote'))}</p>`}</div></footer>`;}


const cafeCart=c=>ui(c).cafeCart||[],cafeProduct=(c,id)=>c.C.cafeProducts?.find(p=>p.id===id),cafeTotal=c=>cafeCart(c).reduce((n,x)=>n+(cafeProduct(c,x.productId)?.priceMinor||0)*x.quantity,0);
const cafePilot=c=>!simplified(c)&&c.state.rules?.cafeOrderPilot===true;
const activeCafeVisits=c=>c.cid()&&c.M.isActiveVisit?rows(c,'visits').filter(v=>c.M.isActiveVisit(c.state,c.cid(),v.id)):[];
function visitLabel(c,v){const bookings=rows(c,'bookings').filter(b=>b.visitId===v.id&&!['cancelled','rejected'].includes(b.status)),access=rows(c,'facilityAccess').filter(x=>x.visitId===v.id&&x.status!=='cancelled');const names=[...bookings.map(b=>localized(c,c.C.services?.find(s=>s.id===b.serviceId)||c.C.classes?.find(s=>s.id===b.classId)||b.snapshot?.serviceNames||text(c,'visit'))),...access.map(x=>localized(c,fac(c,x.facilityId)||text(c,'facility')))];return [c.date(v.date),...new Set(names)].join(' · ');}
function cafeAccount(c){return activeCafeVisits(c).map(v=>`<a class="flowfix-cafe-account" href="#receipt/${esc(c,v.id)}"><span>${esc(c,text(c,'visitAccount'))}</span><strong>${esc(c,visitLabel(c,v))}</strong><span>${esc(c,text(c,'account'))} →</span></a>`).join('');}
function cafeHeader(c,heading,back='discover'){return `<header class="flowfix-cafe-header"><div class="flowfix-cafe-top"><a class="icon-button" href="#${esc(c,back)}" aria-label="${esc(c,text(c,'back'))}">${c.icon('back')}</a>${media('brand','default',{alt:'Sultan Saba',className:'safe-media-cafe-mark'})}${cafePilot(c)?`<a class="icon-button" href="#cafe-cart" aria-label="${esc(c,text(c,'cart'))}"><svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="M3 3h2l3 12h11l2-8H6 M9 19h.01 M18 19h.01"/></svg></a>`:'<span class="flowfix-header-spacer" aria-hidden="true"></span>'}</div><p class="eyebrow">Slim Kafe</p><h1 tabindex="-1">${esc(c,heading)}</h1></header>`;}
function cafeMenu(c){const q=ui(c).menuQuery||'',cat=ui(c).menuCategory||'',all=c.C.cafeProducts||[],cats=[...new Set(all.map(p=>p.category))],list=all.filter(p=>(!cat||p.category===cat)&&[localized(c,p),localized(c,p.descriptions||p.description||'')].join(' ').toLocaleLowerCase(lang(c)).includes(q.toLocaleLowerCase(lang(c))));return `<section class="flowfix-cafe flowfix-cafe-menu">`+cafeHeader(c,text(c,'menu'))+`<form class="flowfix-menu-search" role="search" data-form="revision-menu-filter"><label class="sr-only" for="cafe-search">${esc(c,text(c,'search'))}</label><input id="cafe-search" name="search" type="search" value="${esc(c,q)}" placeholder="${esc(c,text(c,'menuSearch'))}" autocomplete="off">${hidden(c,'category',cat)}<button type="submit" aria-label="${esc(c,text(c,'search'))}">${c.icon('discover')}</button></form><div class="revision-categories">${[['',text(c,'all')],...cats.map(x=>[x,categoryName(c,x)])].map(([id,name])=>`<button type="button" class="chip ${cat===id?'selected':''}" data-action="revision-menu-category" data-id="${esc(c,id)}" aria-pressed="${cat===id}">${esc(c,name)}</button>`).join('')}</div>${simplified(c)?'':`<div class="revision-cafe-banner">${media('cafe','default',{alt:'Slim Kafe'})}<div><span>Slim Kafe</span><h2>${esc(c,text(c,'menuIntro'))}</h2></div></div>`}<div class="revision-menu-grid">${list.map(p=>`<a href="#cafe-product/${esc(c,p.id)}" class="revision-product-card"><span class="eyebrow">${esc(c,categoryName(c,p.category))}</span><h2>${esc(c,localized(c,p))}</h2>${p.descriptions||p.description?`<p class="secondary-menu-description">${esc(c,localized(c,p.descriptions||p.description))}</p>`:''}<div class="cafe-source-tile-footer"><strong>${p.priceMinor===null?esc(c,text(c,'unknownPrice')):c.money(p.priceMinor)}</strong><span class="cafe-source-tile-open" aria-hidden="true">${c.icon('right')}</span></div><span class="sr-only">${esc(c,text(c,'details'))}</span></a>`).join('')||`<p class="flowfix-menu-empty" role="status">${esc(c,text(c,'noResult'))}</p>`}</div><p class="source-note">${esc(c,text(c,'sourcePrice'))}</p>${cafeAccount(c)}${cafePilot(c)&&cafeCart(c).length?a(c,'cart','cafe-cart'):''}</section>`;}
function cafeItem(c,id){const p=cafeProduct(c,id);if(!p)return empty(c);const description=localized(c,p.descriptions||p.description||''),copy=table=>resolve(c,table),glyph=(name,fallback='back')=>root.SpaSourceIcons?.[name]?.replace('<svg ','<svg class="icon source-icon" aria-hidden="true" ')||c.icon(fallback),photo='',canAdd=cafePilot(c)&&p.priceMinor!==null&&p.available!==false;return `<section class="flowfix-cafe flowfix-cafe-item cafe-source-product secondary-menu-detail" data-source="cafe_product">${photo?`<figure class="cafe-source-hero" data-source="hero_002" data-media-slot="image">${photo}</figure>`:''}<a class="icon-button cafe-source-back" href="#discover/cafe" aria-label="${esc(c,text(c,'back'))}">${glyph('lucide:chevron-left')}</a>${photo?`<p class="cafe-source-caption">${esc(c,copy({"tr":"Slim Kafe sofrası","az":"Slim Kafe süfrəsi","ru":"Стол Slim Kafe","en":"Slim Cafe table"}))}</p>`:''}<article class="flowfix-product-information cafe-source-information" data-source="product-detail_003"><div class="cafe-source-eyebrow">${glyph('solar:tea-cup-outline','rights')}<span>${esc(c,copy({"tr":"Kafe Menü","az":"Kafe Menyusu","ru":"Меню кафе","en":"Cafe menu"}))}</span></div><h1 tabindex="-1">${esc(c,localized(c,p))}</h1><p class="price">${p.priceMinor===null?esc(c,text(c,'unknownPrice')):c.money(p.priceMinor)}</p>${description?`<section class="flowfix-product-description" data-source="description_004"><h2>${esc(c,text(c,'description'))}</h2><p>${esc(c,description)}</p></section>`:''}${canAdd?form('revision-cafe-add',hidden(c,'id',id)+`<div class="cafe-source-quantity" data-source="quantity_005"><h2>${esc(c,text(c,'quantity'))}</h2><div class="revision-quantity">${btn(c,'−','revision-quantity-minus','')}<label class="field"><span class="sr-only">${esc(c,text(c,'quantity'))}</span><input name="quantity" value="1" type="number" min="1" max="20" required></label>${btn(c,'+','revision-quantity-plus','')}</div></div><div class="cafe-source-location" data-source="location_006">${input(c,'location',ui(c).cafeLocation||'','text','maxlength="100"')}</div>`+submit(c,'add')):''}<p class="source-note">${esc(c,text(c,'sourcePrice'))}</p>${p.available===false?`<p class="note">${esc(c,text(c,'unavailable'))}</p>`:''}${cafeAccount(c)}</article></section>${canAdd?'':`<footer class="flow-footer"><div class="cafe-source-footer">${a(c,'goMenu','discover/cafe')}</div></footer>`}`;}
function cafeReview(c){
 if(!cafePilot(c))return `<section class="flowfix-cafe">`+cafeHeader(c,text(c,'menu'),'discover/cafe')+`<p class="note">${esc(c,text(c,'menuClosed'))}</p>`+a(c,'goMenu','discover/cafe')+cafeAccount(c)+`</section>`;
 const cart=cafeCart(c);if(!cart.length)return title(c,'cart','discover/cafe')+empty(c)+a(c,'goMenu','discover/cafe');
 const copy=table=>resolve(c,table);
 const glyph=(name,fallback='back')=>root.SpaSourceIcons?.[name]?.replace('<svg ','<svg class="icon source-icon" aria-hidden="true" ')||c.icon(fallback);
 const visits=activeCafeVisits(c),selectedVisit=visits.find(v=>v.id===ui(c).cafeVisitId)||visits[0];
 const priced=cart.every(x=>{const p=cafeProduct(c,x.productId);return p&&Number.isSafeInteger(p.priceMinor)&&p.priceMinor>=0&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=20;});
 const selectedItemsTotal=priced?cafeTotal(c):null;
 const unpriced=copy({"tr":"Menü veya fiyat bilgisi değişti. İlgili ürünü kaldırıp güncel menüden yeniden seçin.","az":"Menyu və ya qiymət məlumatı dəyişib. Məhsulu silib cari menyudan yenidən seçin.","ru":"Состав меню или цена изменились. Удалите товар и выберите его заново в текущем меню.","en":"Menu or pricing information changed. Remove the affected product and select it again from the current menu."});
 const note=copy({"tr":"Bu bir sipariş isteğidir. İşletme kabulü ve hazırlama ayrı adımlardır. Ücret yalnız teslimde ziyaret hesabına eklenir. Bu adımda ödeme alınmaz; hesap işletmede ayrıca kapatılır.","az":"Bu sifariş sorğusudur. Müəssisənin qəbulu və hazırlama ayrı addımlardır. Məbləğ yalnız təhvil zamanı ziyarət hesabına əlavə edilir. Bu addımda ödəniş alınmır; hesab məkanda ayrıca bağlanır.","ru":"Это заявка на заказ. Принятие и приготовление — отдельные этапы. Сумма добавляется в счёт визита только при выдаче. На этом этапе оплаты нет; счёт оплачивается отдельно на месте.","en":"This is an order request. Venue acceptance and preparation are separate steps. The charge is added to your visit account only on delivery. No payment is collected at this step; the account is settled separately at the venue."});
 const rowsMarkup=cart.map((x,i)=>{
  const p=cafeProduct(c,x.productId),known=p&&Number.isSafeInteger(p.priceMinor)&&p.priceMinor>=0;
  const remove=btn(c,'remove','revision-cafe-remove',i).replace('>'+esc(c,text(c,'remove'))+'</button>','>'+glyph('solar:trash-bin-trash-linear','back')+'</button>').replace('class="btn','aria-label="'+esc(c,text(c,'remove')+': '+localized(c,p||x))+'" class="btn commerce-cart-remove');
  return `<article class="commerce-cart-item" data-source="items-list_004"><div class="commerce-cart-item-title"><h2>${esc(c,p?localized(c,p):text(c,'unavailable'))}</h2>${remove}</div><div class="commerce-cart-item-price"><span>${x.quantity} × ${known?c.money(p.priceMinor):esc(c,copy({"tr":"Fiyat teyit bekliyor","az":"Qiymət təsdiq gözləyir","ru":"Цена уточняется","en":"Price awaiting confirmation"}))}</span>${known?`<strong>${c.money(p.priceMinor*x.quantity)}</strong>`:''}</div></article>`;
 }).join('');
 const preferences=visits.length?`<details class="commerce-cart-preferences" ${String(ui(c).cafeLocation||'').trim().length<2?'open':''}><summary>${esc(c,copy({"tr":"Ziyaret ve servis yerini düzenle","az":"Ziyarəti və xidmət yerini dəyiş","ru":"Изменить визит и место подачи","en":"Edit visit and serving location"}))}</summary>${select(c,'activeVisit',visits.map(v=>[v.id,visitLabel(c,v)]),selectedVisit.id)}${input(c,'location',ui(c).cafeLocation||'','text','required maxlength="100"')}</details>`:'';
 const controls=!c.cid()?btn(c,'login','revision-cafe-login',''):!visits.length?`<p>${esc(c,text(c,'noVisit'))}</p>${a(c,'goMenu','discover/cafe')}`:!priced?`<p class="note error commerce-cart-unpriced" role="alert">${esc(c,unpriced)}</p>${a(c,'goMenu','discover/cafe')}`:form('revision-cafe-order',preferences+hidden(c,'total',cafeTotal(c))+`<label class="choice"><input type="checkbox" name="explicit" required><span>${esc(c,text(c,'explicit'))}</span></label>`+submit(c,'order'));
 return `<section class="cafefix-cart commerce-cart-source"><header class="commerce-cart-header" data-source="header_001"><div class="commerce-cart-title"><a class="icon-button" href="#discover/cafe" aria-label="${esc(c,text(c,'goMenu'))}">${glyph('lucide:x')}</a><h1 tabindex="-1">${esc(c,copy({"tr":"Sepetim","az":"Səbətim","ru":"Моя корзина","en":"My basket"}))}</h1><span aria-hidden="true"></span></div>${selectedVisit?`<article class="cafefix-active-visit" data-source="visit-context_002">${glyph('solar:calendar-mark-bold','visits')}<div><small>${esc(c,copy({"tr":"Aktif ziyaret","az":"Aktiv ziyarət","ru":"Текущий визит","en":"Active visit"}))}</small><strong>${esc(c,visitLabel(c,selectedVisit))}</strong>${ui(c).cafeLocation?`<p>${esc(c,ui(c).cafeLocation)}</p>`:''}</div></article>`:''}</header><div class="commerce-cart-content" data-source="scroll-content_003"><div class="commerce-cart-items">${rowsMarkup}</div><div class="cafefix-cart-total" data-source="summary_005">${priced?`<dl class="commerce-cart-amounts"><div data-amount-role="subtotal"><dt>${esc(c,copy({"tr":"Ara Toplam","az":"Ara cəm","ru":"Промежуточная сумма","en":"Subtotal"}))}</dt><dd>${c.money(selectedItemsTotal)}</dd></div><div class="commerce-cart-fee-pending" data-amount-role="fee-information"><dt>${esc(c,copy({"tr":"Ek ücret bilgisi","az":"Əlavə ödəniş məlumatı","ru":"Информация о доплате","en":"Additional charge information"}))}</dt><dd>${esc(c,copy({"tr":"İşletme teyidi bekliyor","az":"Müəssisənin təsdiqi gözlənilir","ru":"Ожидает подтверждения комплекса","en":"Awaiting venue confirmation"}))}</dd></div><div class="commerce-cart-items-total" data-amount-role="selected-items"><dt>${esc(c,copy({"tr":"Seçilen ürünlerin toplamı","az":"Seçilmiş məhsulların cəmi","ru":"Сумма выбранных товаров","en":"Total for selected products"}))}</dt><dd>${c.money(selectedItemsTotal)}</dd></div></dl>`:`<p>${esc(c,unpriced)}</p>`}</div><p class="note commerce-cart-billing-note">${glyph('solar:info-circle-linear','rights')}<span>${esc(c,note)}</span></p>${controls}</div></section>`;
}
function cafeOrders(c,id){if(!c.cid()){c.requireAuth(id?'cafe-order/'+id:'cafe-orders');return '';}const copy={tracking:{"tr":"Sipariş Takibi","az":"Sifarişin izlənməsi","ru":"Статус заказа","en":"Order tracking"},detail:{"tr":"Sipariş Detayı","az":"Sifariş məlumatı","ru":"Состав заказа","en":"Order details"},pending:{"tr":"Henüz gerçekleşmedi","az":"Hələ baş verməyib","ru":"Ещё не выполнено","en":"Not yet completed"},posting:{"tr":"Ücret yalnız teslimde ziyaret hesabına eklenir. Teslim, ödeme alındığı anlamına gelmez; hesap işletmede ayrıca kapatılır. Bu ekran yerel demo kayıtlarını gösterir.","az":"Məbləğ yalnız təhvil zamanı ziyarət hesabına əlavə edilir. Təhvil ödəniş alındığı demək deyil; hesab məkanda ayrıca bağlanır. Bu ekran yerli demo qeydlərini göstərir.","ru":"Сумма добавляется в счёт визита только при выдаче. Выдача не означает оплату; счёт оплачивается отдельно на месте. Здесь показаны локальные демонстрационные записи.","en":"The charge is added to your visit account only on delivery. Delivery does not mean payment was received; the account is settled separately at the venue. This screen shows local demo records."},history:{"tr":"İşlem geçmişi","az":"Əməliyyat tarixçəsi","ru":"История действий","en":"Activity history"}},word=k=>resolve(c,copy[k]),stages=['requested','approved','preparing','delivered'],list=rows(c,'cafeOrders').filter(x=>!id||x.id===id),focused=!!id&&list.length===1;return `<section class="cafefix-orders ${focused?'commerce-order-focused':''}">`+(focused?'':title(c,'orders','discover/cafe'))+(list.map(o=>`<article class="card revision-record cafefix-order"><header class="cafefix-order-header">${media('brand','default',{alt:'Sultan Saba'})}<p>${esc(c,word('tracking'))}</p><${focused?'h1':'h2'} tabindex="-1">${esc(c,text(c,o.status))}</${focused?'h1':'h2'}>${o.cancelRequested?badge(c,'cancel_requested'):''}</header>${stages.includes(o.status)?`<ol class="cafefix-order-timeline">${stages.map((stage,index)=>{const at=(o.history||[]).filter(x=>x.status===stage).at(-1)?.at,current=stage===o.status,reached=index<=stages.indexOf(o.status);return `<li class="${current?'is-current':reached?'is-complete':'is-upcoming'}" ${current?'aria-current="step"':''}><span class="cafefix-step-mark" aria-hidden="true"></span><div><strong>${esc(c,text(c,stage))}</strong>${at?`<time datetime="${esc(c,at)}">${esc(c,new Date(at).toLocaleTimeString(lang(c),{timeZone:'Asia/Baku',hour:'2-digit',minute:'2-digit'}))}</time>`:!reached?`<p>${esc(c,word('pending'))}</p>`:''}</div></li>`;}).join('')}</ol>`:badge(c,o.status)}<section class="cafefix-order-detail"><h3>${esc(c,word('detail'))}</h3><p>${esc(c,o.location||'')}</p><div class="revision-menu">${(o.items||[]).map(x=>`<div class="revision-menu-item"><span>${x.quantity} × ${esc(c,localized(c,x.snapshot||x))}</span><strong>${c.money((x.quantity||0)*(x.priceMinor||0))}</strong></div>`).join('')}</div><div class="cafefix-order-total"><span>${esc(c,text(c,'total'))}</span><strong>${c.money(o.totalMinor||0)}</strong></div>${o.reply?`<p class="note">${esc(c,o.reply)}</p>`:''}</section><p class="cafefix-posting-note">${esc(c,word('posting'))}</p><details class="cafefix-order-history"><summary>${esc(c,word('history'))}</summary>${history(c,o.history)}</details>${focused?'':a(c,'account','receipt/'+o.visitId,'secondary')}${!simplified(c)&&['requested','approved','preparing'].includes(o.status)&&!o.cancelRequested?form('revision-cafe-cancel',hidden(c,'id',o.id)+area(c,'reason')+submit(c,'cancel')):''}</article>`).join('')||empty(c))+a(c,'goMenu','discover/cafe','secondary')+`</section>`+(focused?`<footer class="flow-footer"><div class="commerce-order-footer">${a(c,'account','receipt/'+list[0].visitId,'secondary')}</div></footer>`:'');}
const eventWords={
organization:{"tr":"Organizasyon","az":"Təşkilat","ru":"Организация","en":"Organization"},requestTitle:{"tr":"Grup Etkinlik Talebi","az":"Qrup Tədbiri Müraciəti","ru":"Заявка на групповое мероприятие","en":"Group event request"},quoteTitle:{"tr":"Etkinlik Teklifi","az":"Tədbir Təklifi","ru":"Предложение мероприятия","en":"Event proposal"},planTitle:{"tr":"Etkinlik Programı","az":"Tədbir Planı","ru":"Программа мероприятия","en":"Event program"},timing:{"tr":"Zamanlama","az":"Vaxt planı","ru":"Дата и время","en":"Timing"},eventDetails:{"tr":"Etkinlik ayrıntıları","az":"Tədbir təfərrüatları","ru":"Детали мероприятия","en":"Event details"},requestedScope:{"tr":"Hizmet ve ikram isteğiniz","az":"Xidmət və ikram istəyiniz","ru":"Пожелания по услугам и угощению","en":"Your service and refreshment request"},scopeNote:{"tr":"İsteğinizi yazın. Bu adımda hizmet veya ikram dahil edilmiş sayılmaz; kapsam teklifte ayrıca belirtilir.","az":"İstəyinizi yazın. Bu addımda xidmət və ya ikram daxil edilmiş sayılmır; əhatə təklifdə ayrıca göstərilir.","ru":"Опишите пожелания. На этом этапе услуги и угощение не включены; состав будет указан в предложении.","en":"Describe your wishes. No service or refreshment is included at this step; the proposal specifies the scope separately."},requestAction:{"tr":"Teklif iste","az":"Təklif istə","ru":"Запросить предложение","en":"Request proposal"},requestNote:{"tr":"Talebinizi resepsiyon inceler ve ayrı bir teklif sunar. Henüz alan, uzman veya tarih ayrılmaz.","az":"Müraciəti resepsiya nəzərdən keçirir və ayrıca təklif verir. Hələ məkan, mütəxəssis və ya tarix rezervasiya olunmur.","ru":"Администратор рассмотрит заявку и подготовит предложение. Зоны, специалисты и дата пока не зарезервированы.","en":"Reception reviews your request and provides a separate proposal. No area, specialist or date is reserved yet."},itemized:{"tr":"Hizmet kalemleri","az":"Xidmət maddələri","ru":"Состав предложения","en":"Service items"},allocations:{"tr":"Planlanan tahsisler","az":"Planlaşdırılan ayırmalar","ru":"Планируемые зоны и специалисты","en":"Planned allocations"},quoteNote:{"tr":"Teklifi kabul etmeniz kesin rezervasyon değildir. Resepsiyon son uygunluk kontrolünden sonra planı onaylar; bu adımda ödeme alınmaz.","az":"Təklifi qəbul etmək dəqiq rezervasiya deyil. Resepsiya son uyğunluq yoxlamasından sonra planı təsdiqləyir; bu addımda ödəniş alınmır.","ru":"Принятие предложения не создаёт подтверждённое бронирование. Администратор подтвердит план после итоговой проверки. На этом этапе оплата не взимается.","en":"Accepting a proposal is not a confirmed booking. Reception confirms the plan after a final availability check; no payment is collected at this step."},expiredQuote:{"tr":"Bu teklifin süresi doldu. Yeni teklif için resepsiyonla görüşün.","az":"Bu təklifin müddəti bitib. Yeni təklif üçün resepsiyaya müraciət edin.","ru":"Срок предложения истёк. Обратитесь к администратору за новым предложением.","en":"This proposal has expired. Contact reception for a new proposal."},acceptedNote:{"tr":"Teklif kabul edildi; resepsiyonun son kontrolü bekleniyor.","az":"Təklif qəbul edildi; resepsiyanın son yoxlaması gözlənilir.","ru":"Предложение принято; ожидается итоговая проверка администратора.","en":"Proposal accepted; awaiting reception's final check."},confirmedPlan:{"tr":"Program kesinleşti","az":"Plan təsdiqləndi","ru":"Программа подтверждена","en":"Program confirmed"},confirmedNote:{"tr":"Resepsiyonun onayladığı rezervasyon ve tahsis kayıtları aşağıda. Ödeme durumu ziyaret hesabında izlenir.","az":"Resepsiyanın təsdiqlədiyi rezervasiya və ayırma qeydləri aşağıdadır. Ödəniş vəziyyəti ziyarət hesabında izlənir.","ru":"Ниже записи и зоны, подтверждённые администратором. Статус оплаты отображается в счёте визита.","en":"Bookings and allocations confirmed by reception are shown below. Payment status is tracked in the visit account."},currentPlanTitle:{"tr":"Mevcut onaylı program","az":"Mövcud təsdiqli plan","ru":"Текущая подтверждённая программа","en":"Current confirmed program"},proposalTitle:{"tr":"Değişiklik teklifi","az":"Dəyişiklik təklifi","ru":"Предложение изменений","en":"Change proposal"},proposedNote:{"tr":"Aşağıdaki teklif mevcut programdan ayrıdır. Yeni plan kesinleşene kadar önceki rezervasyonlar korunur.","az":"Aşağıdakı təklif mövcud plandan ayrıdır. Yeni plan təsdiqlənənədək əvvəlki rezervasiyalar saxlanılır.","ru":"Предложение ниже отличается от текущей программы. До подтверждения нового плана прежние записи сохраняются.","en":"The proposal below is separate from the current program. Previous bookings remain until the new plan is confirmed."},participant:{"tr":"Katılımcı","az":"İştirakçı","ru":"Участники","en":"Participant"},organizer:{"tr":"Organizatör","az":"Təşkilatçı","ru":"Организатор","en":"Organizer"},organizerAbsent:{"tr":"Organizatör katılmıyor","az":"Təşkilatçı iştirak etmir","ru":"Организатор не участвует","en":"Organizer not attending"},itinerary:{"tr":"Akış planı","az":"Tədbir axını","ru":"Расписание","en":"Itinerary"},actualAllocations:{"tr":"Kayıtlı tahsisler","az":"Qeydə alınmış ayırmalar","ru":"Зарегистрированные зоны и специалисты","en":"Recorded allocations"},noAllocations:{"tr":"Ayrıntılı tahsis kaydı henüz yok.","az":"Təfərrüatlı ayırma qeydi hələ yoxdur.","ru":"Подробных записей о зонах и специалистах пока нет.","en":"No detailed allocation record yet."},noRecord:{"tr":"Bu etkinlik için kayıtlı rezervasyon bulunmuyor.","az":"Bu tədbir üçün qeydə alınmış rezervasiya yoxdur.","ru":"Для этого мероприятия нет зарегистрированных записей.","en":"There are no recorded bookings for this event."},download:{"tr":"Program özetini HTML olarak indir","az":"Plan xülasəsini HTML kimi endir","ru":"Скачать программу в HTML","en":"Download program summary as HTML"},downloadNote:{"tr":"Kayıtlı programdan üretilen yazdırılabilir HTML dosyası.","az":"Qeydə alınmış plandan yaradılmış çap edilə bilən HTML faylı.","ru":"Печатная HTML-версия зарегистрированной программы.","en":"Printable HTML file generated from the recorded program."},changePlan:{"tr":"Program değişikliği talebi","az":"Plan dəyişikliyi müraciəti","ru":"Запросить изменение программы","en":"Request a program change"},visitAccounts:{"tr":"Bağlı ziyaret hesapları","az":"Əlaqəli ziyarət hesabları","ru":"Связанные счета визитов","en":"Linked visit accounts"},capacity:{"tr":"Ayrılan miktar","az":"Ayrılmış miqdar","ru":"Выделено","en":"Allocated quantity"},room:{"tr":"alan","az":"məkan","ru":"зон","en":"area"},person:{"tr":"kişi","az":"nəfər","ru":"человек","en":"person"},station:{"tr":"yer","az":"yer","ru":"мест","en":"place"},expertUnknown:{"tr":"Uzman bilgisi kayıtta yok","az":"Mütəxəssis məlumatı qeyddə yoxdur","ru":"Специалист в записи не указан","en":"No specialist information in the record"},allocation:{"tr":"Alan tahsisi","az":"Məkan ayırması","ru":"Выделенная зона","en":"Area allocation"},pastPlan:{"tr":"Kayıtlı program","az":"Qeydə alınmış plan","ru":"Зарегистрированная программа","en":"Recorded program"},requestedAt:{"tr":"Talep tarihi","az":"Müraciət tarixi","ru":"Дата заявки","en":"Request date"},myNote:{"tr":"İsteğiniz","az":"İstəyiniz","ru":"Ваши пожелания","en":"Your request"}};
